import * as THREE from 'three/webgpu';
import { texture as textureNode } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture asset
  const textureAsset = ctx.textureLoader.load(config.assets.imageUrl);
  textureAsset.colorSpace = THREE.SRGBColorSpace;

  // Create plane geometry matching atlas aspect ratio (512x320)
  const planeWidth = 2.4;
  const planeHeight = (320 / 512) * planeWidth;

  const planeGeometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // Material using TSL nodes
  const planeMaterial = new THREE.MeshBasicNodeMaterial({
    colorNode: textureNode(textureAsset),
    transparent: true
  });

  // Create plane mesh
  const planeMesh = new THREE.Mesh(planeGeometry, planeMaterial);
  group.add(planeMesh);

  // Render text content via fontAtlas
  if (config.textContent) {
    const textInput = Array.isArray(config.textContent)
      ? config.textContent[0]
      : config.textContent;

    const textString = typeof textInput === 'string'
      ? textInput
      : (textInput.content || 'Features 1');

    const textMesh = ctx.fontAtlas.render({
      text: textString,
      fontSize: 39,
      fontFamily: 'Lora',
      fontWeight: 400,
      fillStyle: config.colors?.ink || '#16161d'
    });

    // Position text label below the card
    textMesh.position.set(0, -planeHeight / 2 - 0.25, 0.01);
    group.add(textMesh);
  }

  // Apply scene transforms
  const [posX, posY, posZ] = config.scenePosition || [-3.2, 1, 0.06];
  const [rotX, rotY, rotZ] = config.sceneRotation || [0, 0, 0];
  const [scaleX, scaleY, scaleZ] = config.sceneScale || [1, 1, 1];

  group.position.set(posX, posY, posZ);
  group.rotation.set(rotX, rotY, rotZ);
  group.scale.set(scaleX, scaleY, scaleZ);

  // Setup event handlers
  group.userData.handlers = {};

  // Setup resource cleanup
  group.userData.cleanup = () => {
    planeGeometry.dispose();
    planeMaterial.dispose();
    textureAsset.dispose();
  };

  return group;
}
